WITH cleaned AS (SELECT *, CONCAT_WS('-', city, supplier_name) AS city_supplier_name_key, CONCAT(supplier_name, ' - ', city) AS supplier_name_city FROM suppliers WHERE city IS NOT NULL), enriched AS (SELECT *, CUME_DIST() OVER (ORDER BY rating DESC NULLS FIRST) AS rating_cume_dist, LAST_VALUE(rating, TRUE) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_rating FROM cleaned WHERE supplier_name IS NULL), base AS (SELECT id, country, rating, supplier_name_city, rating_cume_dist, last_known_rating, SUBSTRING(country, 1, 4) AS country_prefix FROM enriched WHERE city IS NOT NULL), base_suppliers AS (SELECT *, CAST(rating AS INT) AS rating_int FROM base WHERE country IN ('UK', 'DE', 'SG')), scored AS (SELECT *, ROUND(rating / SUM(rating) OVER (PARTITION BY country), 4) AS rating_share, STDDEV_SAMP(rating_int) OVER (PARTITION BY country) AS country_stddev_samp_rating_int FROM base_suppliers), metrics AS (SELECT *, LAST_VALUE(country_stddev_samp_rating_int, TRUE) OVER (PARTITION BY country ORDER BY rating_cume_dist, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country_stddev_samp_rating_int, SUM(country_stddev_samp_rating_int) OVER w_ordered AS country_sum_country_stddev_samp_rating_int, AVG(last_known_rating) OVER w_grp AS last_known_rating_avg_5_prior FROM scored WINDOW w_ordered AS (PARTITION BY country), w_grp AS (PARTITION BY country ORDER BY country_stddev_samp_rating_int, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING)), cleaned_suppliers AS (SELECT *, CAST(rating AS INT) AS rating_int_2 FROM metrics WHERE rating_share IS NULL) SELECT country, MAX(rating_int_2) FILTER (WHERE country = 'DE') AS de_max_rating_int_2, MIN(rating_int) AS min_rating_int, APPROX_PERCENTILE(rating_int, 0.95) AS rating_int_p95, SUM(CASE WHEN country = 'UK' THEN rating_cume_dist ELSE 0 END) AS uk_rating_cume_dist, COUNT(DISTINCT country) AS distinct_countries FROM cleaned_suppliers GROUP BY country ORDER BY min_rating_int;
